using System;
class Animal { public virtual string Speak() { return "Animal"; } }
class Dog : Animal { public override string Speak() { return "Dog (override)"; } }
class Puppy : Dog { public new string Speak() { return "Puppy (new)"; } }
class Program
{
    static void Main()
    {
        Puppy p = new Puppy();
        Animal a = p;   // same object, three static views
        Dog d = p;
        // override: the virtual slot is replaced, so Dog's code is reached
        Console.WriteLine("Animal ref: " + a.Speak());
        Console.WriteLine("Dog ref:    " + d.Speak());
        // new: a separate method, chosen by the static type
        Console.WriteLine("Puppy ref:  " + p.Speak());
    }
}

using System;
interface IReport { string Render(); }
// Abstract base: shared state + template method, subclasses fill the blanks
abstract class ReportBase : IReport
{
    protected readonly string Title;
    protected ReportBase(string title) { Title = title; }
    public string Render() { return Header() + Body() + "--end--"; }
    protected string Header() { return "== " + Title + " ==\n"; }
    protected abstract string Body();
}
class SalesReport : ReportBase
{
    public SalesReport() : base("Sales") { }
    protected override string Body() { return "total=120\n"; }
}
// A class may implement many interfaces but has one base class
class Program
{
    static void Main()
    {
        IReport r = new SalesReport();   // consumers only see the interface
        Console.Write(r.Render());
        Console.WriteLine();
        Console.WriteLine("Is IReport: " + (r is IReport) + ", is ReportBase: " + (r is ReportBase));
    }
}

using System;
class Base
{
    int b = Log("Base field init");
    public Base() { Console.WriteLine("Base ctor body"); Hello(); }
    public virtual void Hello() { Console.WriteLine("Base.Hello"); }
    protected static int Log(string s) { Console.WriteLine(s); return 1; }
}
class Derived : Base
{
    int d = Log("Derived field init");
    string name;
    public Derived() { name = "set in body"; Console.WriteLine("Derived ctor body"); }
    // Runs from Base's constructor, before Derived's body assigns name
    public override void Hello() { Console.WriteLine("Derived.Hello name=" + (name == null ? "null" : name)); }
}
class Program
{
    static void Main()
    {
        Console.WriteLine("new Derived():");
        new Derived();
    }
}

using System;
using System.Collections.Generic;
class BadKey
{
    public int Id;
    public BadKey(int id) { Id = id; }
    public override bool Equals(object o) { BadKey k = o as BadKey; return k != null && k.Id == Id; }
}
class GoodKey : BadKey
{
    public GoodKey(int id) : base(id) { }
    // Same field as Equals, so equal objects get equal hashes
    public override int GetHashCode() { return Id.GetHashCode(); }
}
class Program
{
    static void Main()
    {
        var bad = new HashSet<BadKey>();
        bad.Add(new BadKey(7)); bad.Add(new BadKey(7));
        Console.WriteLine("Equals only:       count=" + bad.Count + " contains=" + bad.Contains(new BadKey(7)));
        var good = new HashSet<GoodKey>();
        good.Add(new GoodKey(7)); good.Add(new GoodKey(7));
        Console.WriteLine("Equals+GetHashCode: count=" + good.Count + " contains=" + good.Contains(new GoodKey(7)));
    }
}

using System;
interface IPrinter { string Run(); }
interface IScanner { string Run(); }
class Multi : IPrinter, IScanner
{
    // Explicit: callable only through the interface type
    string IPrinter.Run() { return "printing"; }
    string IScanner.Run() { return "scanning"; }
    public string Run() { return "plain Multi.Run"; }
}
struct Counter : IComparable
{
    public int V;
    int IComparable.CompareTo(object o) { return V.CompareTo(((Counter)o).V); }
}
class Program
{
    static void Main()
    {
        Multi m = new Multi();
        Console.WriteLine(m.Run());                 // class member
        Console.WriteLine(((IPrinter)m).Run());     // same name, different meaning
        Console.WriteLine(((IScanner)m).Run());
        Counter c = new Counter { V = 1 };
        // m.CompareTo would not compile; the cast to the interface boxes a copy
        Console.WriteLine("CompareTo: " + ((IComparable)c).CompareTo(new Counter { V = 5 }));
    }
}

using System;
interface IShipping { decimal Cost(decimal weightKg); }
class Standard : IShipping { public decimal Cost(decimal w) { return 5m + w * 1m; } }
class Express : IShipping { public decimal Cost(decimal w) { return 15m + w * 2m; } }
// Decorator: adds behaviour by wrapping, no subclass per combination
class Logged : IShipping
{
    readonly IShipping inner;
    public Logged(IShipping i) { inner = i; }
    public decimal Cost(decimal w)
    {
        decimal c = inner.Cost(w);
        Console.WriteLine("  [log] " + inner.GetType().Name + " for " + w + "kg = " + c);
        return c;
    }
}
class Checkout
{
    IShipping shipping;                       // strategy, swappable at run time
    public Checkout(IShipping s) { shipping = s; }
    public void Use(IShipping s) { shipping = s; }
    public decimal Total(decimal items, decimal kg) { return items + shipping.Cost(kg); }
}
class Program
{
    static void Main()
    {
        Checkout c = new Checkout(new Standard());
        Console.WriteLine("Standard total: " + c.Total(100m, 3m));
        c.Use(new Logged(new Express()));
        Console.WriteLine("Logged express total: " + c.Total(100m, 3m));
    }
}

using System;
class Shape { public virtual string Name() { return "Shape"; } }
class Circle : Shape
{
    // sealed override: no class below Circle can override Name again
    public sealed override string Name() { return "Circle"; }
}
sealed class Leaf : Circle
{
    // public override string Name() ... would be error CS0239
}
sealed class Point { public int X = 3; }
class Program
{
    static void Main()
    {
        Shape s = new Leaf();
        Console.WriteLine(s.Name());
        // Type check against a sealed type is an exact method-table compare
        object o = new Point();
        Console.WriteLine("o is Point: " + (o is Point));
        Console.WriteLine("Leaf sealed: " + typeof(Leaf).IsSealed + ", Circle sealed: " + typeof(Circle).IsSealed);
        object t = new Leaf();
        Console.WriteLine("exact type: " + t.GetType().Name);
    }
}

using System;
class A { public virtual string F() { return "A.F"; } public virtual string G() { return "A.G"; } }
class B : A
{
    public override string F() { return "B.F -> base: " + base.F(); } // base.F() is a non-virtual call
}
class C
{
    public int x;
    public string Hi() { return "Hi (does not touch this)"; }
}
class Program
{
    static void Main()
    {
        A a = new B();               // MethodTable of B: slots F (B's), G (inherited)
        Console.WriteLine(a.F());    // picks the slot via the object's real type
        Console.WriteLine(a.G());
        C c = null;
        try { Console.WriteLine(c.Hi()); }   // callvirt does a null check even if unused
        catch (NullReferenceException) { Console.WriteLine("NullReferenceException from callvirt"); }
    }
}

using System;
interface ILogger { void Log(string m); }
// C# 7 stand-in for a default interface method: an extension method
static class LoggerDefaults
{
    public static void Warn(this ILogger l, string m) { l.Log("WARN: " + m); }
}
class Console1 : ILogger { public void Log(string m) { Console.WriteLine("console " + m); } }
class Prefixed : ILogger
{
    public void Log(string m) { Console.WriteLine("prefixed " + m); }
    // Own version hides the "default"; it is picked only for the static type Prefixed
    public void Warn(string m) { Console.WriteLine("custom warn " + m); }
}
class Program
{
    static void Main()
    {
        ILogger a = new Console1();
        a.Warn("disk low");                 // uses the shared default
        Prefixed p = new Prefixed();
        p.Warn("disk low");                 // class member wins
        ((ILogger)p).Warn("disk low");      // through the interface: default again
    }
}

using System;
class Rectangle
{
    public virtual int Width { get; set; }
    public virtual int Height { get; set; }
    public int Area() { return Width * Height; }
}
class Square : Rectangle
{
    // Keeps the sides equal, breaking the rectangle's postcondition
    public override int Width { set { base.Width = value; base.Height = value; } get { return base.Width; } }
    public override int Height { set { base.Width = value; base.Height = value; } get { return base.Height; } }
}
class Program
{
    static void Resize(Rectangle r)
    {
        r.Width = 5; r.Height = 4;
        Console.WriteLine(r.GetType().Name + ": expected 20, got " + r.Area());
    }
    static void Main()
    {
        Resize(new Rectangle());
        Resize(new Square());   // LSP violation
    }
}

using System;
interface IVisitor { void Hit(Asteroid a); void Hit(Ship s); }
abstract class Thing
{
    public abstract void CollideWith(Thing other);        // 1st dispatch: on this
    public abstract void Accept(IVisitor v);              // 2nd dispatch: on the other
}
class Asteroid : Thing
{
    public override void CollideWith(Thing o) { o.Accept(new V("Asteroid")); }
    public override void Accept(IVisitor v) { v.Hit(this); }   // 'this' is statically Asteroid
}
class Ship : Thing
{
    public override void CollideWith(Thing o) { o.Accept(new V("Ship")); }
    public override void Accept(IVisitor v) { v.Hit(this); }
}
class V : IVisitor
{
    string first; public V(string f) { first = f; }
    public void Hit(Asteroid a) { Console.WriteLine(first + " hits Asteroid"); }
    public void Hit(Ship s) { Console.WriteLine(first + " hits Ship"); }
}
class Program
{
    static void Main()
    {
        Thing[] all = { new Asteroid(), new Ship() };
        foreach (Thing a in all) foreach (Thing b in all) a.CollideWith(b);  // runtime types on both sides
    }
}

using System;
// Hand-written equivalent of what a record generates (C# 7 style)
class Point : IEquatable<Point>
{
    public readonly int X, Y;
    public Point(int x, int y) { X = x; Y = y; }
    public bool Equals(Point o) { return o != null && GetType() == o.GetType() && X == o.X && Y == o.Y; } // type check ~ EqualityContract
    public override bool Equals(object o) { return Equals(o as Point); }
    public override int GetHashCode() { return unchecked(X * 31 + Y); }
    public static bool operator ==(Point a, Point b) { return ReferenceEquals(a, null) ? ReferenceEquals(b, null) : a.Equals(b); }
    public static bool operator !=(Point a, Point b) { return !(a == b); }
    public override string ToString() { return "Point { X = " + X + ", Y = " + Y + " }"; }
}
class Point3 : Point { public Point3(int x, int y) : base(x, y) { } }
class Program
{
    static void Main()
    {
        Point a = new Point(1, 2), b = new Point(1, 2);
        Console.WriteLine(a + " == " + b + " : " + (a == b));
        Console.WriteLine("same hash: " + (a.GetHashCode() == b.GetHashCode()));
        Console.WriteLine("base vs derived equal: " + a.Equals(new Point3(1, 2)));
    }
}

using System;
using System.Collections.Generic;
class Result { public bool Ok; public string Info; }
interface IPaymentProvider { Result Authorise(decimal amount); }
class CardProvider : IPaymentProvider
{
    public Result Authorise(decimal a) { return new Result { Ok = a <= 500m, Info = a <= 500m ? "approved" : "declined: limit" }; }
}
class WalletProvider : IPaymentProvider
{
    public Result Authorise(decimal a) { return new Result { Ok = true, Info = "wallet ok" }; }
}
// Decorator adds retry-style cross-cutting behaviour without touching providers
class Logging : IPaymentProvider
{
    readonly IPaymentProvider inner;
    public Logging(IPaymentProvider i) { inner = i; }
    public Result Authorise(decimal a)
    {
        Result r = inner.Authorise(a);
        Console.WriteLine("  [log] " + inner.GetType().Name + " " + a + " -> " + r.Info);
        return r;
    }
}
class Program
{
    static void Main()
    {
        var registry = new Dictionary<string, IPaymentProvider>();   // registered by key
        registry["card"] = new Logging(new CardProvider());
        registry["wallet"] = new Logging(new WalletProvider());
        Console.WriteLine("ok=" + registry["card"].Authorise(100m).Ok);
        Console.WriteLine("ok=" + registry["card"].Authorise(900m).Ok);   // expected decline = result, not exception
        Console.WriteLine("ok=" + registry["wallet"].Authorise(900m).Ok);
    }
}

using System;
using System.Collections.Generic;
class Bag
{
    protected List<string> items = new List<string>();
    public virtual void Add(string s) { items.Add(s); }
    // Base secretly calls the virtual Add: an undocumented implementation detail
    public virtual void AddAll(string[] all) { foreach (string s in all) Add(s); }
}
class CountingBag : Bag
{
    public int Added;
    public override void Add(string s) { Added++; base.Add(s); }
    public override void AddAll(string[] all) { Added += all.Length; base.AddAll(all); }
}
class Program
{
    static void Main()
    {
        CountingBag b = new CountingBag();
        b.AddAll(new[] { "a", "b", "c" });
        // Expected 3, but AddAll counted 3 and then each Add counted again
        Console.WriteLine("Added = " + b.Added + " (expected 3)");
    }
}
